begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select is((select enabled from public.community_feature_controls where feature='comments'),false,'Comments independently start closed');
select ok(not has_table_privilege('authenticated','public.community_comments','insert'),'Direct client comment insertion is denied');
select ok(not has_table_privilege('authenticated','public.community_comments','update'),'Direct client comment edit is denied');
select ok(not has_table_privilege('anon','public.community_comments','select'),'Anonymous comment reads are denied');
update public.community_operations set enabled=true,enrollment=true,discovery=true,publish=true,engagement=true,cohort_required=false;
update public.community_feature_controls set enabled=true where feature='comments';
insert into auth.users(id,email) select ('c1560000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'comment-'||i||'@mizyun.test' from generate_series(1,6)i;
update public.profiles set birth_year=1990 where id::text like 'c1560000%';
insert into public.community_profiles(user_id,handle,display_name,avatar_symbol,status,generation,terms_version,terms_accepted_at,adult_declared_at)
select id,'comm156_'||right(id::text,12),'Synthetic member','SP','active',1,'2026-09-30',now(),now() from auth.users where id::text like 'c1560000%';
insert into public.community_moderation_staff(user_id,active) values
('c1560000-0000-4000-8000-000000000005',true),('c1560000-0000-4000-8000-000000000006',true);
create temporary table comment_moderation_state(report uuid,appeal uuid);
grant all on comment_moderation_state to authenticated;
insert into public.community_relationships(follower_user_id,target_user_id,status) values
('c1560000-0000-4000-8000-000000000002','c1560000-0000-4000-8000-000000000001','approved'),
('c1560000-0000-4000-8000-000000000003','c1560000-0000-4000-8000-000000000001','approved');
insert into public.workouts(id,user_id,name,started_at,completed_at,details) values
('a1560000-0000-4000-8000-000000000001','c1560000-0000-4000-8000-000000000001','PRIVATE',now()-interval '1 minute',now(),'{"workoutLifecycle":{"kind":"session"}}'),
('a1560000-0000-4000-8000-000000000002','c1560000-0000-4000-8000-000000000001','PRIVATE2',now()-interval '1 minute',now(),'{"workoutLifecycle":{"kind":"session"}}');
insert into public.shared_activities(id,user_id,source_workout_id,category,shared_day,enrollment_generation) values
('a1560000-0000-4000-8000-000000000003','c1560000-0000-4000-8000-000000000001','a1560000-0000-4000-8000-000000000001','strength',(now() at time zone 'UTC')::date::text,1),
('a1560000-0000-4000-8000-000000000004','c1560000-0000-4000-8000-000000000001','a1560000-0000-4000-8000-000000000002','strength',(now() at time zone 'UTC')::date::text,1);
set local role authenticated;
set local request.jwt.claim.role='authenticated';
set local request.jwt.claim.sub='c1560000-0000-4000-8000-000000000001';
select is(public.community_comments('list','{"activityId":"a1560000-0000-4000-8000-000000000003"}')->>'enabled','false','Each published workout starts with comments closed');
select lives_ok($$select public.community_comments('settings','{"activityId":"a1560000-0000-4000-8000-000000000003","enabled":true}')$$,'Author explicitly enables own thread');
select lives_ok($$select public.community_comments('settings','{"activityId":"a1560000-0000-4000-8000-000000000004","enabled":true}')$$,'Author enables second test thread');
set local request.jwt.claim.sub='c1560000-0000-4000-8000-000000000002';
select throws_ok($$select public.community_comments('settings','{"activityId":"a1560000-0000-4000-8000-000000000003","enabled":false}')$$,'P0001','community_unavailable','Follower cannot control author thread');
select throws_ok($$select public.community_comments('upsert','{"activityId":"a1560000-0000-4000-8000-000000000003","id":"b1560000-0000-4000-8000-000000000001","operationId":"d1560000-0000-4000-8000-000000000001","expectedVersion":0,"body":"See https://example.com","mentions":[]}')$$,'P0001','community_invalid_action','Link text fails at direct RPC boundary');
select throws_ok($$select public.community_comments('upsert','{"activityId":"a1560000-0000-4000-8000-000000000003","id":"b1560000-0000-4000-8000-000000000001","operationId":"d1560000-0000-4000-8000-000000000001","expectedVersion":0,"body":"Nice workout","mentions":["c1560000-0000-4000-8000-000000000001"]}')$$,'P0001','community_unavailable','Membership does not imply mention consent');
set local request.jwt.claim.sub='c1560000-0000-4000-8000-000000000001';
select lives_ok($$select public.community_comments('preferences','{"allowMentions":true}')$$,'Recipient deliberately opts in to mentions');
set local request.jwt.claim.sub='c1560000-0000-4000-8000-000000000002';
select is(jsonb_array_length(public.community_comments('candidates','{"activityId":"a1560000-0000-4000-8000-000000000003"}')->'items'),1,'Only permitted consenting participant is suggested');
select is(public.community_comments('upsert','{"activityId":"a1560000-0000-4000-8000-000000000003","id":"b1560000-0000-4000-8000-000000000001","operationId":"d1560000-0000-4000-8000-000000000001","expectedVersion":0,"body":"Nice workout","mentions":["c1560000-0000-4000-8000-000000000001"]}')->>'version','1','Explicit comment and mention create version1');
select is(public.community_comments('upsert','{"activityId":"a1560000-0000-4000-8000-000000000003","id":"b1560000-0000-4000-8000-000000000001","operationId":"d1560000-0000-4000-8000-000000000001","expectedVersion":0,"body":"Nice workout","mentions":["c1560000-0000-4000-8000-000000000001"]}')->>'version','1','Committed lost-response replay preserves version');
select is((select count(*) from public.community_comments where id='b1560000-0000-4000-8000-000000000001'),1::bigint,'Retry creates one row');
select throws_ok($$select mentions from public.community_comments where id='b1560000-0000-4000-8000-000000000001'$$,'42501',null,'Even author raw reads cannot expose unfiltered recipient UUIDs');
select throws_ok($$select generation from public.community_comments where id='b1560000-0000-4000-8000-000000000001'$$,'42501',null,'Enrollment internals remain outside the raw social projection');
select throws_ok($$select public.community_comments('upsert','{"activityId":"a1560000-0000-4000-8000-000000000003","id":"b1560000-0000-4000-8000-000000000001","operationId":"d1560000-0000-4000-8000-000000000001","expectedVersion":0,"body":"Changed content","mentions":["c1560000-0000-4000-8000-000000000001"]}')$$,'P0001','community_conflict','Reused operation ID cannot change text');
select throws_ok($$select public.community_comments('upsert','{"activityId":"a1560000-0000-4000-8000-000000000004","id":"b1560000-0000-4000-8000-000000000002","parentId":"b1560000-0000-4000-8000-000000000001","operationId":"d1560000-0000-4000-8000-000000000002","expectedVersion":0,"body":"Reply","mentions":[]}')$$,'P0001','community_unavailable','Forged cross-thread parent is denied');
select lives_ok($$select public.community_comments('upsert','{"activityId":"a1560000-0000-4000-8000-000000000003","id":"b1560000-0000-4000-8000-000000000002","parentId":"b1560000-0000-4000-8000-000000000001","operationId":"d1560000-0000-4000-8000-000000000002","expectedVersion":0,"body":"Reply","mentions":[]}')$$,'One bounded reply depth works');
select throws_ok($$select public.community_comments('upsert','{"activityId":"a1560000-0000-4000-8000-000000000003","id":"b1560000-0000-4000-8000-000000000003","parentId":"b1560000-0000-4000-8000-000000000002","operationId":"d1560000-0000-4000-8000-000000000003","expectedVersion":0,"body":"Nested reply","mentions":[]}')$$,'P0001','community_unavailable','Unbounded nested replies are denied');
select is(jsonb_array_length(public.community_comments('list','{"activityId":"a1560000-0000-4000-8000-000000000003","limit":1}')->'items'),1,'Thread page size is bounded');
select ok(public.community_comments('list','{"activityId":"a1560000-0000-4000-8000-000000000003","limit":1}')->>'nextCursor' is not null,'More rows produce keyset cursor');
select is(jsonb_array_length(public.community_comments('list',jsonb_build_object('activityId','a1560000-0000-4000-8000-000000000003','limit',1,'cursor',public.community_comments('list','{"activityId":"a1560000-0000-4000-8000-000000000003","limit":1}')->>'nextCursor'))->'items'),1,'Next page has no duplicate first row');
select throws_ok($$select public.community_comments('report','{"id":"b1560000-0000-4000-8000-000000000001","reason":"spam"}')$$,'P0001','community_unavailable','Self-report cannot create a moderation case');
set local request.jwt.claim.sub='c1560000-0000-4000-8000-000000000004';
select throws_ok($$select public.community_comments('list','{"activityId":"a1560000-0000-4000-8000-000000000003"}')$$,'P0001','community_unavailable','Unrelated principal cannot enumerate thread');
select is((select count(*) from public.community_comments),0::bigint,'RLS also denies unrelated raw reads');
set local request.jwt.claim.sub='c1560000-0000-4000-8000-000000000001';
select is(jsonb_array_length(public.community_comments('mentionsInbox','{}')->'items'),1,'Mention has one current generic inbox event');
select lives_ok($$select public.community_comments('list','{"activityId":"a1560000-0000-4000-8000-000000000003"}')$$,'List records bounded exact safety receipts');
select lives_ok($$select public.community_comments('report','{"id":"b1560000-0000-4000-8000-000000000001","reason":"offensive_content"}')$$,'Current comment can be reported through existing case boundary');
set local request.jwt.claim.sub='c1560000-0000-4000-8000-000000000003';
insert into public.community_blocks(blocker_user_id,blocked_user_id) values(auth.uid(),'c1560000-0000-4000-8000-000000000002');
select is(jsonb_array_length(public.community_comments('list','{"activityId":"a1560000-0000-4000-8000-000000000003"}')->'items'),0,'Blocked root and its replies do not leak through counts/previews');
select throws_ok($$select mentions from public.community_comments where id='b1560000-0000-4000-8000-000000000001'$$,'42501',null,'Blocked viewer cannot bypass mention consent through raw PostgREST columns');
set local request.jwt.claim.sub='c1560000-0000-4000-8000-000000000002';
select is(public.community_comments('upsert','{"activityId":"a1560000-0000-4000-8000-000000000003","id":"b1560000-0000-4000-8000-000000000001","operationId":"d1560000-0000-4000-8000-000000000004","expectedVersion":1,"body":"Great consistency","mentions":["c1560000-0000-4000-8000-000000000001"]}')->>'version','2','Author edits with exact version');
select throws_ok($$select public.community_comments('upsert','{"activityId":"a1560000-0000-4000-8000-000000000003","id":"b1560000-0000-4000-8000-000000000001","operationId":"d1560000-0000-4000-8000-000000000005","expectedVersion":1,"body":"Stale edit","mentions":[]}')$$,'P0001','community_conflict','Stale edit does not overwrite new content');
set local request.jwt.claim.sub='c1560000-0000-4000-8000-000000000001';
select is(jsonb_array_length(public.community_comments('mentionsInbox','{}')->'items'),1,'Edit does not duplicate mention notification');
select lives_ok($$select public.community_comments('preferences','{"allowMentions":false}')$$,'Recipient revokes mention consent');
select is(jsonb_array_length(public.community_comments('mentionsInbox','{}')->'items'),0,'Consent revocation immediately suppresses mention inbox');
select throws_ok($$select mentions from public.community_comments where id='b1560000-0000-4000-8000-000000000001'$$,'42501',null,'Opted-out recipient UUID cannot be recovered through raw columns');
select is(jsonb_array_length(public.community_comments('list','{"activityId":"a1560000-0000-4000-8000-000000000003"}')->'items'->0->'mentions'),0,'Authorized DTO hides opted-out recipients despite retained dedupe metadata');
reset role;
set local request.jwt.claim.role='service_role';
update public.community_feature_controls set enabled=false where feature='comments';
set local role authenticated;
set local request.jwt.claim.role='authenticated';
set local request.jwt.claim.sub='c1560000-0000-4000-8000-000000000002';
select throws_ok($$select public.community_comments('list','{"activityId":"a1560000-0000-4000-8000-000000000003"}')$$,'P0001','community_unavailable','Feature freeze denies new comment browsing');
select lives_ok($$select public.community_comments('delete','{"id":"b1560000-0000-4000-8000-000000000001","expectedVersion":2}')$$,'Privacy delete works during feature freeze');
select lives_ok($$select public.community_comments('delete','{"id":"b1560000-0000-4000-8000-000000000001","expectedVersion":2}')$$,'Lost delete response retry stays idempotent');
set local request.jwt.claim.sub='c1560000-0000-4000-8000-000000000001';
select lives_ok($$select public.community_comments('report','{"id":"b1560000-0000-4000-8000-000000000001","reason":"spam"}')$$,'Removed comment remains reportable through exact prior receipt');
insert into comment_moderation_state(report) select id from public.community_submit_report('comment','b1560000-0000-4000-8000-000000000002','offensive_content');
set local request.jwt.claim.sub='c1560000-0000-4000-8000-000000000002';
select throws_ok($$select * from public.community_apply_moderation_action((select report from comment_moderation_state),'remove','Synthetic unsafe reply')$$,'P0001','community_access_denied','Ordinary comment author cannot exercise staff removal');
set local request.jwt.claim.sub='c1560000-0000-4000-8000-000000000005';
select throws_ok($$select * from public.community_apply_moderation_action((select report from comment_moderation_state),'remove','Synthetic unsafe reply')$$,'P0001','community_access_denied','Registered moderator still requires AAL2');
set local request.jwt.claims='{"aal":"aal2"}';
select lives_ok($$select * from public.community_claim_report((select report from comment_moderation_state))$$,'Independent named moderator claims comment case');
select lives_ok($$select * from public.community_apply_moderation_action((select report from comment_moderation_state),'remove','Synthetic unsafe reply')$$,'Target-specific removal works even during feature freeze');
select throws_ok($$select * from public.community_apply_moderation_action((select report from comment_moderation_state),'remove','Repeat action')$$,'P0001','community_conflict','Resolved comment case rejects duplicate staff action');
set local request.jwt.claim.sub='c1560000-0000-4000-8000-000000000002';
insert into comment_moderation_state(appeal) select id from public.community_create_moderation_appeal((select report from comment_moderation_state where report is not null),'Please review this removal');
set local request.jwt.claim.sub='c1560000-0000-4000-8000-000000000005';
select throws_ok($$select * from public.community_resolve_moderation_appeal((select appeal from comment_moderation_state where appeal is not null),'approved','Own review')$$,'P0001','community_access_denied','Original comment moderator cannot review own action');
set local request.jwt.claim.sub='c1560000-0000-4000-8000-000000000006';
select lives_ok($$select * from public.community_resolve_moderation_appeal((select appeal from comment_moderation_state where appeal is not null),'approved','Independent review')$$,'Independent AAL2 reviewer can resolve comment appeal');
reset role;
select is((select body from public.community_comments where id='b1560000-0000-4000-8000-000000000002'),null,'Approved appeal does not resurrect erased comment text');
select is((select status from public.community_profiles where user_id='c1560000-0000-4000-8000-000000000002'),'active','Removing comment leaves author profile enrolled');
set local role authenticated;
set local request.jwt.claims='{}';
set local request.jwt.claim.sub='c1560000-0000-4000-8000-000000000002';
select is((select count(*) from public.community_export_page('comments',null,500)),2::bigint,'Export includes own comment categories despite feature freeze');
select lives_ok($$select public.community_withdraw_profile()$$,'Community withdrawal works while feature disabled');
reset role;
select is((select count(*) from public.community_comments where user_id='c1560000-0000-4000-8000-000000000002'),0::bigint,'Withdrawal erases authored comment text before reenrollment');
select is((select count(*) from public.community_comment_operations where user_id='c1560000-0000-4000-8000-000000000002'),0::bigint,'Withdrawal cannot replay old comment operations');
select * from finish();
rollback;
